void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    bool close = false;

    vec3 c, cfloor;

    for (float i = 0.; i < 7. && !close; i++) {
        float N = pow(2.,9.-i);
        vec2 uvfloor = floor(uv * N) / N;
        c = texture(iChannel0, uv).xyz;
        cfloor = texture(iChannel0, uvfloor).xyz;
        float cdiff = dot(abs(c-cfloor), vec3(1.,1.,1.));
        if (cdiff < 0.1) {
            fragColor = vec4(cfloor, 1.);
            close = true;
        }

    }
}
